using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.VTS.VisitasGeneradas;namespace GraphApi.Services.VTS.VisitasGeneradas{    public class VisitasGeneradasService : IVisitasGeneradasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public VisitasGeneradasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadVisitasGeneradas>> GetVisitasGeneradas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM vts.vsVisitasGeneradas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadVisitasGeneradas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetVisitasGeneradasDynamic(            int? visitaGeneradaID,            string? nombreVisitante,            int? usuarioVisitadoID,            string? nombreVisitado,            string? correoVisitado,            int? casaID,            string? direccionCasa,            string? numeroExtCasa,            int? tipoIdentificacionID,            string? tipoIdentificacion,            string? numeroIdentificacion,            string? rutaDocumento,            string? codigoQR,            DateTime? fechaEmision,            DateTime? fechaExpira,            bool? bUsado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "VisitaGeneradaID, NombreVisitante, UsuarioVisitadoID, NombreVisitado, CorreoVisitado, CasaID, DireccionCasa, NumeroExtCasa, TipoIdentificacionID, TipoIdentificacion, NumeroIdentificacion, RutaDocumento, CodigoQR, FechaEmision, FechaExpira, bUsado, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM vts.vsVisitasGeneradas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (visitaGeneradaID.HasValue)            {                vSql.Append(" AND VisitaGeneradaID = @VisitaGeneradaID");                vParameters.Add("VisitaGeneradaID",visitaGeneradaID);            }            if (!string.IsNullOrWhiteSpace(nombreVisitante))            {                vSql.Append(" AND NombreVisitante LIKE @NombreVisitante");                vParameters.Add("NombreVisitante",$"%{nombreVisitante}%");            }            if (!string.IsNullOrWhiteSpace(nombreVisitado))            {                vSql.Append(" AND NombreVisitado LIKE @NombreVisitado");                vParameters.Add("NombreVisitado",$"%{nombreVisitado}%");            }            if (!string.IsNullOrWhiteSpace(correoVisitado))            {                vSql.Append(" AND CorreoVisitado LIKE @CorreoVisitado");                vParameters.Add("CorreoVisitado",$"%{correoVisitado}%");            }            if (!string.IsNullOrWhiteSpace(direccionCasa))            {                vSql.Append(" AND DireccionCasa LIKE @DireccionCasa");                vParameters.Add("DireccionCasa",$"%{direccionCasa}%");            }            if (!string.IsNullOrWhiteSpace(numeroExtCasa))            {                vSql.Append(" AND NumeroExtCasa LIKE @NumeroExtCasa");                vParameters.Add("NumeroExtCasa",$"%{numeroExtCasa}%");            }            if (!string.IsNullOrWhiteSpace(tipoIdentificacion))            {                vSql.Append(" AND TipoIdentificacion LIKE @TipoIdentificacion");                vParameters.Add("TipoIdentificacion",$"%{tipoIdentificacion}%");            }            if (!string.IsNullOrWhiteSpace(numeroIdentificacion))            {                vSql.Append(" AND NumeroIdentificacion LIKE @NumeroIdentificacion");                vParameters.Add("NumeroIdentificacion",$"%{numeroIdentificacion}%");            }            if (!string.IsNullOrWhiteSpace(rutaDocumento))            {                vSql.Append(" AND RutaDocumento LIKE @RutaDocumento");                vParameters.Add("RutaDocumento",$"%{rutaDocumento}%");            }            if (!string.IsNullOrWhiteSpace(codigoQR))            {                vSql.Append(" AND CodigoQR LIKE @CodigoQR");                vParameters.Add("CodigoQR",$"%{codigoQR}%");            }            if (bUsado.HasValue)            {                vSql.Append(" AND bUsado = @bUsado");                vParameters.Add("bUsado", bUsado.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadVisitasGeneradas> CreateVisitasGeneradas(clCreateVisitasGeneradas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO vts.VisitasGeneradas                (NombreVisitante, UsuarioVisitadoID, CasaID, TipoIdentificacionID, NumeroIdentificacion, RutaDocumento, CodigoQR, FechaEmision, FechaExpira, bUsado, bEliminado, Column_20, Column_21, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@NombreVisitante, @UsuarioVisitadoID, @CasaID, @TipoIdentificacionID, @NumeroIdentificacion, @RutaDocumento, @CodigoQR, @FechaEmision, @FechaExpira, @bUsado, @bEliminado, @Column_20, @Column_21, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.NombreVisitante,                objInput.UsuarioVisitadoID,                objInput.CasaID,                objInput.TipoIdentificacionID,                objInput.NumeroIdentificacion,                objInput.RutaDocumento,                objInput.CodigoQR,                objInput.FechaEmision,                objInput.FechaExpira,                objInput.bUsado,                objInput.bEliminado,                objInput.Column_20,                objInput.Column_21,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT VisitaGeneradaID, NombreVisitante, UsuarioVisitadoID, NombreVisitado, CorreoVisitado, CasaID, DireccionCasa, NumeroExtCasa, TipoIdentificacionID, TipoIdentificacion, NumeroIdentificacion, RutaDocumento, CodigoQR, FechaEmision, FechaExpira, bUsado, bEliminado                FROM vts.vsVisitasGeneradas (NOLOCK)                WHERE VisitaGeneradaID = @VisitaGeneradaID;";            var vReadParams = new { VisitaGeneradaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadVisitasGeneradas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el VisitasGenerada con ID {vNewId}.");            return vCreated;        }        public async Task<clReadVisitasGeneradas?> UpdateVisitasGeneradas(clUpdateVisitasGeneradas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("VisitaGeneradaID", objInput.VisitaGeneradaID);            if (objInput.NombreVisitante is not null)            {                vSets.Add("NombreVisitante = @NombreVisitante");                vParameters.Add("NombreVisitante", objInput.NombreVisitante);            }            if (objInput.UsuarioVisitadoID != null)            {                vSets.Add("UsuarioVisitadoID = @UsuarioVisitadoID");                vParameters.Add("UsuarioVisitadoID", objInput.UsuarioVisitadoID);            }            if (objInput.CasaID != null)            {                vSets.Add("CasaID = @CasaID");                vParameters.Add("CasaID", objInput.CasaID);            }            if (objInput.TipoIdentificacionID != null)            {                vSets.Add("TipoIdentificacionID = @TipoIdentificacionID");                vParameters.Add("TipoIdentificacionID", objInput.TipoIdentificacionID);            }            if (objInput.NumeroIdentificacion is not null)            {                vSets.Add("NumeroIdentificacion = @NumeroIdentificacion");                vParameters.Add("NumeroIdentificacion", objInput.NumeroIdentificacion);            }            if (objInput.RutaDocumento is not null)            {                vSets.Add("RutaDocumento = @RutaDocumento");                vParameters.Add("RutaDocumento", objInput.RutaDocumento);            }            if (objInput.CodigoQR is not null)            {                vSets.Add("CodigoQR = @CodigoQR");                vParameters.Add("CodigoQR", objInput.CodigoQR);            }            if (objInput.FechaEmision != null)            {                vSets.Add("FechaEmision = @FechaEmision");                vParameters.Add("FechaEmision", objInput.FechaEmision);            }            if (objInput.FechaExpira != null)            {                vSets.Add("FechaExpira = @FechaExpira");                vParameters.Add("FechaExpira", objInput.FechaExpira);            }            if (objInput.bUsado != null)            {                vSets.Add("bUsado = @bUsado");                vParameters.Add("bUsado", objInput.bUsado);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            if (objInput.Column_20 != null)            {                vSets.Add("Column_20 = @Column_20");                vParameters.Add("Column_20", objInput.Column_20);            }            if (objInput.Column_21 != null)            {                vSets.Add("Column_21 = @Column_21");                vParameters.Add("Column_21", objInput.Column_21);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE vts.VisitasGeneradas                SET {vSetClause}                WHERE VisitaGeneradaID = @VisitaGeneradaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT VisitaGeneradaID, NombreVisitante, UsuarioVisitadoID, NombreVisitado, CorreoVisitado, CasaID, DireccionCasa, NumeroExtCasa, TipoIdentificacionID, TipoIdentificacion, NumeroIdentificacion, RutaDocumento, CodigoQR, FechaEmision, FechaExpira, bUsado, bEliminado                FROM vts.vsVisitasGeneradas (NOLOCK)                WHERE VisitaGeneradaID = @VisitaGeneradaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadVisitasGeneradas>(sSelect, new {  objInput.VisitaGeneradaID });        }        public async Task<bool> DeleteVisitasGeneradas(int nVisitasGeneradasID)        {            const string sSql = @"                DELETE FROM vts.VisitasGeneradas                WHERE VisitaGeneradaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nVisitasGeneradasID });            return vAffected > 0;        }    }}